import csv
import pandas as pd
from datetime import datetime, timedelta
import sys

def format_file(input_path):
    # Read the CSV file
    df = pd.read_csv(input_path)

    # Assuming the 4th column is at index 3 (0-based indexing)
    # Adjust time values in the 4th column by subtracting 3 hours
    def adjust_time(time_str):
        try:
            # Try different time formats
            time_formats = ['%H:%M:%S', '%H:%M', '%I:%M:%S %p', '%I:%M %p']
            for fmt in time_formats:
                try:
                    time_obj = datetime.strptime(str(time_str).strip(), fmt)
                    adjusted_time = time_obj - timedelta(hours=3)
                    return adjusted_time.strftime(fmt)
                except ValueError:
                    continue
            # If none of the formats work, return original value
            return time_str
        except Exception:
            # If any other error occurs, return the original value
            return time_str

    # Apply the adjustment to the 4th column (index 3)
    if len(df.columns) > 3:
        df.iloc[:, 3] = df.iloc[:, 3].apply(adjust_time)
    else:
        raise ValueError("CSV file does not have a 4th column")

    # Write the adjusted data to Excel file
    output_path = '/tmp/mcp-workspace/audit-export.xlsx'
    df.to_excel(output_path, index=False)

    print(f"Adjusted data written to {output_path}")
    return output_path

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python format.py <input_csv_path>")
        sys.exit(1)

    input_path = sys.argv[1]
    try:
        format_file(input_path)
    except Exception as e:
        print(f"Error processing file: {e}")
        sys.exit(1)
